 66	/** An open club of $members members and $points standing, kept by a founder of $language and $band. */
 67	function allianceFitClub(string $tag, string $language, AiActivityBand|null $band, int $members = 1, int $points = 0): Alliance
 68	{
 69	    $founder = User::factory()->create(['lang' => $language]);
 70	
 71	    if ($band !== null) {
 72	        allianceFitProfile($founder->id, $band, AiArchetype::Casual);
 73	    }
 74	
 75	    $club = Alliance::unguarded(fn (): Alliance => Alliance::create([
 76	        'alliance_tag' => $tag,
 77	        'alliance_name' => 'Alliance ' . $tag,
 78	        'founder_user_id' => $founder->id,
 79	        'is_open' => true,
 80	        'external_text' => 'Active players welcome',
 81	    ]));
 82	
 83	    allianceFitMember($club->id, $founder->id);
 84	
 85	    for ($member = 1; $member < $members; $member++) {
 86	        allianceFitMember($club->id, User::factory()->create()->id);
 87	    }
 88	
 89	    AllianceHighscore::unguarded(fn () => AllianceHighscore::create([
 90	        'alliance_id' => $club->id,
 91	        'general' => $points,
 92	        'economy' => $points,
 93	        'research' => 0,
 94	        'military' => 0,
 95	    ]));
 96	
 97	    return $club;
 98	}
