   16	/**
   17	 * Picks the alliance a human-like account would apply to, from host data alone.
   18	 *
   19	 * The join decision is "which club will actually take me, and can I keep up with it" (alliance
   20	 * FAQ). The account's rank against the population stays the first filter: a weak account looks
   21	 * for a mass/open club, a strong one for a high points-per-member core, a mid one balances the
   22	 * two (all in resources/behavior/alliance_fit.yaml). Among the clubs the rank admits, the fit rule
   23	 * decides: the applicant's language and activity band against the club's, both read from host
   24	 * state — the club's through its founder. A club no account of this language and pace fits is
   25	 * never asked, so the account stays free for the pass's founder half; the club that then appears
   26	 * carries that account's language and pace, so a cohort spreads over clubs instead of piling into
   27	 * one. An alliance that already rejected the account is never re-applied to.
   28	 */
   29	class AllianceChoice
   30	{
   31	    private const FIT_FILE = '/resources/behavior/alliance_fit.yaml';
   32	
   33	    /** @var array<string, mixed>|null */
   34	    private array|null $policy = null;
   35	
   36	    private bool $policyRead = false;
   37	
   38	    public function choose(int $playerId): ?Alliance
   39	    {
   40	        $policy = $this->policy();
   41	        $rank = (int) Highscore::query()->where('player_id', $playerId)->value('general_rank');
   42	        $population = (int) Highscore::query()->where('general_rank', '>', 0)->count();
   43	
   44	        if ($policy === null || $rank <= 0 || $population <= 0) {
   45	            return null;
   46	        }
   47	
   48	        $ratio = $rank / $population;
   49	        $account = $this->accountFit($playerId);
   50	        $best = null;
   51	        $bestScore = -INF;
   52	
   53	        foreach ($this->openCandidates($playerId) as $alliance) {
   54	            $club = $this->clubFit($alliance);
   55	
   56	            if ($this->crowded($alliance, $policy) || ! $this->fits($account, $club, $policy['fit'])) {
   57	                continue;
   58	            }
   59	
   60	            $score = $this->tierScore($alliance, $ratio, $policy['tier']) + $this->fitScore($account, $club, $policy['fit']);
   61	
   62	            if ($score > $bestScore) {
   63	                $best = $alliance;
   64	                $bestScore = $score;
   65	            }
   66	        }
   67	
   68	        return $best;
   69	    }
   70	
   71	    /**
   72	     * Whether some open alliance fits the account. Without one the pass's founder half gives the
   73	     * account a club of its own, whose language and pace are the account's own — so the cohort's
   74	     * clubs are founded by accounts of different archetypes instead of all draining into the
   75	     * first club that exists.
   76	     */
   77	    public function hasOpenCandidate(int $playerId): bool
   78	    {
   79	        $policy = $this->policy();
   80	
   81	        if ($policy === null) {
   82	            return $this->openCandidates($playerId) !== [];
   83	        }
   84	
   85	        $account = $this->accountFit($playerId);
   86	
   87	        foreach ($this->openCandidates($playerId) as $alliance) {
   88	            if (! $this->crowded($alliance, $policy) && $this->fits($account, $this->clubFit($alliance), $policy['fit'])) {
   89	                return true;
   90	            }
   91	        }
   92	
   93	        return false;
   94	    }
   95	
   96	    /**
   97	     * Whether the club the account sits in still fits it: the same language and pace rule that picked
   98	     * it. A club that does not is one a player leaves, which is how a cohort that all joined one club
   99	     * spreads out instead of staying piled into it.
  100	     */
  101	    public function currentClubFits(int $playerId): bool
  102	    {
  103	        $policy = $this->policy();
  104	        $allianceId = User::query()->whereKey($playerId)->value('alliance_id');
  105	        $club = $allianceId === null ? null : Alliance::query()->find($allianceId);
  106	
  107	        if ($policy === null || $club === null) {
  108	            return true;
  109	        }
  110	
  111	        return ! $this->crowded($club, $policy) && $this->fits($this->accountFit($playerId), $this->clubFit($club), $policy['fit']);
  112	    }
  113	
  114	    /** Whether the club already holds most of the AI accounts, which is when players split off. */
  115	    private function crowded(Alliance $alliance, array $policy): bool
  116	    {
  117	        $accounts = AiProfile::query()->where('enabled', true)->count();
  118	        $held = User::query()->where('alliance_id', $alliance->id)
  119	            ->whereIn('id', AiProfile::query()->where('enabled', true)->select('player_id'))->count();
  120	
  121	        return $held >= (int) $policy['crowded_min_members'] && $held / $accounts > (float) $policy['crowded_share'];
  122	    }
  123	
  124	    /** @return list<Alliance> */
  125	    private function openCandidates(int $playerId): array
  126	    {
  127	        return array_values(
  128	            Alliance::query()
  129	                ->where('is_open', true)
  130	                ->whereDoesntHave('applications', fn ($query) => $query
  131	                    ->where('user_id', $playerId)
  132	                    ->where('status', AllianceApplication::STATUS_REJECTED))
  133	                ->get()
  134	                ->reject(fn (Alliance $alliance): bool => $this->readsFounderAsExploitative($playerId, $alliance))
  135	                ->all(),
  136	        );
  137	    }
  138	
  139	    /**
  140	     * A wary account will not join a club whose founder it models as likely to exploit it, so a
  141	     * Defect read removes that alliance from the account's candidates. An absent relationship or
  142	     * an absent driver read keeps the alliance in the running, exactly as the native choice did.
  143	     */
  144	    private function readsFounderAsExploitative(int $playerId, Alliance $alliance): bool
  145	    {
  146	        return app(PsychSimTheoryOfMind::class)->stanceToward($playerId, (int) $alliance->founder_user_id) === AiToMStance::Defect;
  147	    }
  148	
  149	    /** @return array{language: string|null, band: int|null} */
  150	    private function accountFit(int $playerId): array
  151	    {
  152	        return ['language' => $this->language($playerId), 'band' => $this->band($playerId)];
  153	    }
  154	
  155	    /**
  156	     * The club's own language and pace, read from its founder: the one account whose host state
  157	     * stands for the club the founder keeps.
  158	     *
  159	     * @return array{language: string|null, band: int|null}
  160	     */
  161	    private function clubFit(Alliance $alliance): array
  162	    {
  163	        $founderId = (int) $alliance->founder_user_id;
  164	
  165	        return ['language' => $this->language($founderId), 'band' => $this->band($founderId)];
  166	    }
  167	
  168	    /** The account's declared client language, or null when the host holds none. */
  169	    private function language(int $playerId): string|null
  170	    {
  171	        $lang = strtolower(trim((string) User::query()->whereKey($playerId)->value('lang')));
  172	
  173	        return $lang === '' ? null : $lang;
  174	    }
  175	
  176	    /** How much the account is around, from its own profile; null when it states no pace. */
  177	    private function band(int $playerId): int|null
  178	    {
  179	        return AiProfile::query()->where('player_id', $playerId)->first()?->activity_band?->value;
  180	    }
  181	
  182	    private function fits(array $account, array $club, array $fit): bool
  183	    {
  184	        if ($account['language'] !== null && $club['language'] !== null && $account['language'] !== $club['language']) {
  185	            return false;
  186	        }
  187	
  188	        return $this->bandDistance($account['band'], $club['band']) <= (int) $fit['band']['tolerance'];
  189	    }
  190	
  191	    /** Steps between two paces; an unstated pace on either side is no distance at all. */
  192	    private function bandDistance(int|null $account, int|null $club): int
  193	    {
  194	        if ($account === null || $club === null) {
  195	            return 0;
  196	        }
  197	
  198	        return abs($account - $club);
  199	    }
  200	
  201	    private function fitScore(array $account, array $club, array $fit): float
  202	    {
  203	        return $this->languageScore($account['language'], $club['language'], $fit['language'])
  204	            + $this->bandScore($account['band'], $club['band'], $fit['band']);
  205	    }
  206	
  207	    private function languageScore(string|null $account, string|null $club, array $weights): float
  208	    {
  209	        if ($account === null || $club === null) {
  210	            return 0.0;
  211	        }
  212	
  213	        return (float) ($account === $club ? $weights['match'] : $weights['mismatch']);
  214	    }
  215	
  216	    private function bandScore(int|null $account, int|null $club, array $weights): float
  217	    {
  218	        if ($account === null || $club === null) {
  219	            return 0.0;
  220	        }
  221	
  222	        return match ($this->bandDistance($account, $club)) {
  223	            0 => (float) $weights['match'],
  224	            1 => (float) $weights['neighbour'],
  225	            default => (float) $weights['mismatch'],
  226	        };
  227	    }
  228	
  229	    private function tierScore(Alliance $alliance, float $rankRatio, array $tier): float
  230	    {
